import { ReactNode, FC } from 'react';

type PullRefreshStatus = 'normal' | 'pulling' | 'loosing' | 'loading' | 'success';
interface PullRefreshProps {
    /** 是否刷新中 */
    refreshing: boolean;
    /** 刷新回调 */
    onRefresh: () => void | Promise<void>;
    /** 刷新阈值 (rpx) */
    threshold?: number;
    /** 下拉文案 */
    pullingText?: string;
    /** 释放文案 */
    loosingText?: string;
    /** 加载文案 */
    loadingText?: string;
    /** 成功文案 */
    successText?: string;
    /** 成功展示时长 (ms) */
    successDuration?: number;
    /** 是否禁用 */
    disabled?: boolean;
    /** 自定义头部内容 */
    head?: (status: PullRefreshStatus) => ReactNode;
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}

declare const PullRefresh: FC<PullRefreshProps>;

export { PullRefresh, PullRefresh as default };
export type { PullRefreshProps, PullRefreshStatus };
